<?php
namespace ExcelHerbal\ERP7\Finance;
use ExcelHerbal\ERP7\Core\Input;use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Database\Transaction;use ExcelHerbal\ERP7\Domain\DomainException;use ExcelHerbal\ERP7\Inventory\StockService;use ExcelHerbal\ERP7\Security\Actor;use ExcelHerbal\ERP7\Security\Audit;use ExcelHerbal\ERP7\Security\Capabilities;use ExcelHerbal\ERP7\Security\Guard;
final class FinanceExpenseService{
 public static function expenses(Actor $a,int $branch):array{Guard::any($a,[Capabilities::EXPENSE_CREATE,Capabilities::EXPENSE_APPROVE,Capabilities::FINANCE_VIEW]);if(!$a->hasBranch($branch))throw new DomainException('Branch is outside effective authority.','branch_forbidden',403);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT e.*,h.name expense_head,a.code payment_account_code,a.name payment_account_name FROM ".Db::table('expenses')." e JOIN ".Db::table('expense_heads')." h ON h.id=e.expense_head_id JOIN ".Db::table('accounts')." a ON a.id=e.payment_account_id WHERE e.company_id=%d AND e.branch_id=%d ORDER BY e.id DESC LIMIT 200",$a->companyId,$branch),ARRAY_A);}
 public static function expense(Actor $a,int $branch,int $head,float $amount,int $account,string $date,string $desc):array{$date=Input::date($date,'Expense date');$amount=round($amount,2);Guard::branch($a,$branch,Capabilities::EXPENSE_CREATE);BranchDayGuard::assertOpen($a,$branch,$date);if($amount<=0)throw new DomainException('Expense amount must be positive.');AccountingService::paymentAccount($a,$account);$db=Db::wpdb();if(!(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('expense_heads')." WHERE id=%d AND company_id=%d AND active=1",$head,$a->companyId)))throw new DomainException('Expense head not found.');Db::mustInsert($db,Db::table('expenses'),['company_id'=>$a->companyId,'branch_id'=>$branch,'expense_head_id'=>$head,'amount'=>$amount,'payment_account_id'=>$account,'status'=>'pending','expense_date'=>$date,'description'=>$desc,'created_by'=>$a->employeeId,'created_at'=>Db::now()]);$id=(int)$db->insert_id;Audit::add($a,'expense.create','expense',$id,['branch_id'=>$branch]);return['id'=>$id,'status'=>'pending'];}
 public static function expenseDecision(Actor $a,int $id,bool $approve):array{return Transaction::run(function()use($a,$id,$approve){$db=Db::wpdb();$t=Db::table('expenses');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Expense not found.','expense_not_found',404);Guard::branch($a,(int)$r['branch_id'],Capabilities::EXPENSE_APPROVE);BranchDayGuard::assertOpen($a,(int)$r['branch_id'],(string)$r['expense_date']);if($r['status']!=='pending')throw new DomainException('Expense not pending.');if((int)$r['created_by']===$a->employeeId)throw new DomainException('Maker cannot approve own expense.','maker_checker_required',409);$status=$approve?'approved':'rejected';$journal=null;if($approve){$head=$db->get_row($db->prepare("SELECT * FROM ".Db::table('expense_heads')." WHERE id=%d",(int)$r['expense_head_id']),ARRAY_A);$journal=AccountingService::post($a,(int)$r['branch_id'],'expense',$id,$r['expense_date'].' 12:00:00',[['account_id'=>(int)$head['expense_account_id'],'debit'=>(float)$r['amount']],['account_id'=>(int)$r['payment_account_id'],'credit'=>(float)$r['amount']]],'Expense approval');}Db::mustUpdate($db,$t,['status'=>$status,'approved_by'=>$a->employeeId,'approved_at'=>Db::now(),'journal_entry_id'=>$journal],['id'=>$id]);return['id'=>$id,'status'=>$status,'journal_entry_id'=>$journal];});}
}
